  1083→
  1084→        // 工具函数
  1085→        function random(min, max) {
  1086→            return Math.floor(Math.random() * (max - min + 1)) + min;
  1087→        }
  1088→
  1089→        function formatTime(seconds) {
  1090→            const mins = Math.floor(seconds / 60);
  1091→            const secs = seconds % 60;
  1092→            return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  1093→        }
  1094→
  1095→        function showToast(message, type = 'success') {
  1096→            const toast = document.createElement('div');
  1097→            toast.className = `toast ${type}`;
  1098→            toast.textContent = message;
  1099→            document.body.appendChild(toast);
  1100→            setTimeout(() => toast.remove(), 3000);
  1101→        }
  1102→
  1103→        function showSection(sectionId) {
  1104→            document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
  1105→            document.getElementById(sectionId).classList.add('active');
  1106→        }
  1107→
  1108→        // 获取数字范围
  1109→        function getNumberRange(grade) {
  1110→            switch(grade) {
  1111→                case 1: return { min: 1, max: 10 };
  1112→                case 2: return { min: 1, max: 50 };
  1113→                case 3: return { min: 1, max: 100 };
  1114→                case 4: return { min: 1, max: 500 };
  1115→                case 5: return { min: 1, max: 1000 };
  1116→                case 6: return { min: 1, max: 5000 };
  1117→                default: return { min: 1, max: 100 };
  1118→            }
  1119→        }
  1120→
  1121→        // 生成口算题
  1122→        function generateOralQuestion(grade, difficulty, operation) {
  1123→            const { min, max } = getNumberRange(grade);
  1124→
  1125→            switch(operation) {
  1126→                case 'add':
  1127→                    let a1 = random(min, max);
  1128→                    let b1 = random(min, max);
  1129→                    if (difficulty === 'easy') {
  1130→                        a1 = random(1, Math.min(9, max));
  1131→                        b1 = random(1, Math.min(9, max));
  1132→                    }
  1133→                    return { type: 'oral', question: `${a1} + ${b1}`, answer: a1 + b1, display: `${a1} + ${b1} = ?` };
  1134→
  1135→                case 'subtract':
  1136→                    let ans1 = random(min, max);
  1137→                    let b_sub = random(min, ans1);
  1138→                    let a_sub = ans1 + b_sub;
  1139→                    if (difficulty === 'easy') {
  1140→                        ans1 = random(1, Math.min(9, max));
  1141→                        b_sub = random(1, ans1);
  1142→                        a_sub = ans1 + b_sub;
  1143→                    }
  1144→                    return { type: 'oral', question: `${a_sub} - ${b_sub}`, answer: ans1, display: `${a_sub} - ${b_sub} = ?` };
  1145→
  1146→                case 'multiply':
  1147→                    if (grade === 2) {
  1148→                        const ma = random(1, 9);
  1149→                        const mb = random(1, 9);
  1150→                        return { type: 'oral', question: `${ma} × ${mb}`, answer: ma * mb, display: `${ma} × ${mb} = ?` };
  1151→                    } else if (grade === 3) {
  1152→                        const ma = random(10, 99);
  1153→                        const mb = random(2, 9);
  1154→                        return { type: 'oral', question: `${ma} × ${mb}`, answer: ma * mb, display: `${ma} × ${mb} = ?` };
  1155→                    } else {
  1156→                        const ma = random(10, 99);
  1157→                        const mb = random(10, difficulty === 'easy' ? 20 : 99);
  1158→                        return { type: 'oral', question: `${ma} × ${mb}`, answer: ma * mb, display: `${ma} × ${mb} = ?` };
  1159→                    }
  1160→
  1161→                case 'divide':
  1162→                    let db, dans;
  1163→                    if (grade === 3) {
  1164→                        db = random(2, 9);
  1165→                        dans = random(1, 12);
  1166→                    } else {
  1167→                        db = random(2, difficulty === 'easy' ? 9 : 20);
  1168→                        dans = random(1, 50);
  1169→                    }
  1170→                    const da = db * dans;
  1171→                    return { type: 'oral', question: `${da} ÷ ${db}`, answer: dans, display: `${da} ÷ ${db} = ?` };
  1172→
  1173→                default:
  1174→                    return { type: 'oral', question: '2 + 3', answer: 5, display: '2 + 3 = ?' };
  1175→            }
  1176→        }
  1177→
  1178→        // 生成竖式题
  1179→        function generateVerticalQuestion(grade, difficulty, operation) {
  1180→            const { min, max } = getNumberRange(grade);
  1181→
  1182→            switch(operation) {
  1183→                case 'add':
  1184→                    let va1 = random(min, max);
  1185→                    let vb1 = random(min, max);
  1186→                    // 确保是两位数或三位数，适合竖式
  1187→                    if (grade <= 3) {
  1188→                        va1 = random(10, Math.min(99, max));
  1189→                        vb1 = random(10, Math.min(99, max));
  1190→                    } else {
  1191→                        va1 = random(100, Math.min(999, max));
  1192→                        vb1 = random(100, Math.min(999, max));
  1193→                    }
  1194→                    return {
  1195→                        type: 'vertical',
  1196→                        num1: va1,
  1197→                        num2: vb1,
  1198→                        operator: '+',
  1199→                        answer: va1 + vb1,
  1200→                        display: `${va1} + ${vb1}`
  1201→                    };
  1202→
  1203→                case 'subtract':
  1204→                    let vans = random(min, Math.floor(max * 0.7));
  1205→                    let vb_sub = random(Math.floor(min * 0.5), vans);
  1206→                    let va_sub = vans + vb_sub;
  1207→                    if (grade <= 3) {
  1208→                        vans = random(10, Math.min(99, max));
  1209→                        vb_sub = random(10, vans);
  1210→                        va_sub = vans + vb_sub;
  1211→                    } else {
  1212→                        vans = random(100, Math.min(999, max));
  1213→                        vb_sub = random(100, vans);
  1214→                        va_sub = vans + vb_sub;
  1215→                    }
  1216→                    return {
  1217→                        type: 'vertical',
  1218→                        num1: va_sub,
  1219→                        num2: vb_sub,
  1220→                        operator: '-',
  1221→                        answer: vans,
  1222→                        display: `${va_sub} - ${vb_sub}`
  1223→                    };
  1224→
  1225→                case 'multiply':
  1226→                    if (grade === 3) {
  1227→                        const vma = random(11, 99);
  1228→                        const vmb = random(2, 9);
  1229→                        return {
  1230→                            type: 'vertical',
  1231→                            num1: vma,
  1232→                            num2: vmb,
  1233→                            operator: '×',
  1234→                            answer: vma * vmb,
  1235→                            display: `${vma} × ${vmb}`
  1236→                        };
  1237→                    } else {
  1238→                        const vma = random(11, 99);
  1239→                        const vmb = random(11, difficulty === 'easy' ? 20 : 99);
  1240→                        return {
  1241→                            type: 'vertical',
  1242→                            num1: vma,
  1243→                            num2: vmb,
  1244→                            operator: '×',
  1245→                            answer: vma * vmb,
  1246→                            display: `${vma} × ${vmb}`
  1247→                        };
  1248→                    }
  1249→
  1250→                case 'divide':
  1251→                    let vdb, vdans;
  1252→                    if (grade === 3) {
  1253→                        vdb = random(2, 9);
  1254→                        vdans = random(10, 50);
  1255→                    } else {
  1256→                        vdb = random(2, 20);
  1257→                        vdans = random(10, 100);
  1258→                    }
  1259→                    const vda = vdb * vdans;
  1260→                    return {
  1261→                        type: 'vertical',
  1262→                        num1: vda,
  1263→                        num2: vdb,
  1264→                        operator: '÷',
  1265→                        answer: vdans,
  1266→                        display: `${vda} ÷ ${vdb}`
  1267→                    };
  1268→
  1269→                default:
  1270→                    return {
  1271→                        type: 'vertical',
  1272→                        num1: 123,
  1273→                        num2: 45,
  1274→                        operator: '+',
  1275→                        answer: 168,
  1276→                        display: '123 + 45'
  1277→                    };
  1278→            }
  1279→        }
