  1281→        // 生成所有题目
  1282→        function generateQuestions() {
  1283→            const grade = parseInt(document.getElementById('gradeSelect').value);
  1284→            const difficulty = document.getElementById('difficultySelect').value;
  1285→
  1286→            const operationCheckboxes = document.querySelectorAll('.checkbox-item input[type="checkbox"]:checked');
  1287→            const operations = Array.from(operationCheckboxes).map(cb => cb.value).filter(op => ['add', 'subtract', 'multiply', 'divide'].includes(op));
  1288→
  1289→            if (operations.length === 0) {
  1290→                showToast('请至少选择一种运算类型', 'error');
  1291→                return false;
  1292→            }
  1293→
  1294→            const oralChecked = document.getElementById('oralCheck').checked;
  1295→            const verticalChecked = document.getElementById('verticalCheck').checked;
  1296→
  1297→            // 验证至少选择一种题型
  1298→            if (!oralChecked && !verticalChecked) {
  1299→                showToast('⚠️ 请至少选择一种题型（口算题或竖式题）', 'error');
  1300→                return false;
  1301→            }
  1302→
  1303→            // 验证运算类型
  1304→            if (operations.length === 0) {
  1305→                showToast('⚠️ 请至少选择一种运算类型（加减乘除）', 'error');
  1306→                return false;
  1307→            }
  1308→
  1309→            questions = [];
  1310→
  1311→            // 生成口算题
  1312→            if (oralChecked) {
  1313→                const oralCount = parseInt(document.getElementById('oralCount').value);
  1314→                for (let i = 0; i < oralCount; i++) {
  1315→                    const op = operations[random(0, operations.length - 1)];
  1316→                    questions.push(generateOralQuestion(grade, difficulty, op));
