  1329→ // 不打乱顺序，保持第一部分口算，第二部分竖式
  1330→
  1331→            // 记录各部分的题目数量
  1332→            const oralCount = oralChecked ? parseInt(document.getElementById('oralCount').value) : 0;
  1333→            const verticalCount = verticalChecked ? parseInt(document.getElementById('verticalCount').value) : 0;
  1334→
  1335→            settings = { grade, difficulty, oralChecked, verticalChecked, oralCount, verticalCount };
