  1691→        // 生成打印试卷
  1692→        function generatePrint(copies = 1, sameQuestions = true) {
  1693→            const printContent = document.getElementById('printContent');
  1694→            let html = '';
  1695→
  1696→            // 保存原始设置
  1697→            const originalSettings = {...settings};
  1698→
  1699→            for (let copyIndex = 0; copyIndex < copies; copyIndex++) {
  1700→                // 如果不是使用相同题目，则重新生成题目
  1701→                if (!sameQuestions && copyIndex > 0) {
  1702→                    // 重新生成题目
  1703→                    const oralChecked = originalSettings.oralChecked;
  1704→                    const verticalChecked = originalSettings.verticalChecked;
  1705→                    const grade = originalSettings.grade;
  1706→                    const difficulty = originalSettings.difficulty;
  1707→
  1708→                    const operationCheckboxes = document.querySelectorAll('.checkbox-item input[type="checkbox"]:checked');
  1709→                    const operations = Array.from(operationCheckboxes).map(cb => cb.value).filter(op => ['add', 'subtract', 'multiply', 'divide'].includes(op));
  1710→
  1711→                    questions = [];
  1712→
  1713→                    if (oralChecked) {
  1714→                        const oralCount = originalSettings.oralCount || 0;
  1715→                        for (let i = 0; i < oralCount; i++) {
  1716→                            const op = operations[random(0, operations.length - 1)];
  1717→                            questions.push(generateOralQuestion(grade, difficulty, op));
  1718→                        }
  1719→                    }
  1720→
  1721→                    if (verticalChecked) {
  1722→                        const verticalCount = originalSettings.verticalCount || 0;
  1723→                        for (let i = 0; i < verticalCount; i++) {
  1724→                            const op = operations[random(0, operations.length - 1)];
  1725→                            questions.push(generateVerticalQuestion(grade, difficulty, op));
  1726→                        }
  1727→                    }
  1728→                } else if (copyIndex > 0) {
  1729→                    // 使用相同题目，不需要重新生成
  1730→                } else {
  1731→                    // 第一份，需要先生成题目
  1732→                    if (!generateQuestions()) {
  1733→                        showToast('⚠️ 生成试卷失败，请检查设置', 'error');
  1734→                        return;
  1735→                    }
  1736→                }
  1737→
  1738→                const oralCount = settings.oralCount || 0;
  1739→                const verticalCount = settings.verticalCount || 0;
  1740→
  1741→                // 每份试卷用一个wrapper包裹，避免内部元素被分页规则影响
  1742→                html += '<div class="print-copy-wrapper">';
  1743→
  1744→                // 每份试卷都添加抬头
